class Solution { public: int numSpecial(vector<vector<int>>& mat){vector<int> rows(mat.size()),cols(mat[0].size());for(int row=0;row<(int)mat.size();++row)for(int col=0;col<(int)mat[0].size();++col)if(mat[row][col]){++rows[row];++cols[col];}int answer=0;for(int row=0;row<(int)mat.size();++row)for(int col=0;col<(int)mat[0].size();++col)answer+=mat[row][col]&&rows[row]==1&&cols[col]==1;return answer;} };
